sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))

_PASS = 0
_FAIL = 0
_FAILURES: list[tuple[str, str]] = []
_CURRENT_TEST_LABEL = ""
_FAILURE_DETAIL_LINE_LIMIT = 80
_FAILURE_POINT_LINE_LIMIT = 180
_FAILURE_POINT_HINT_LIMIT = 6
_FINAL_FAILURE_POINT_HEADING = "FAILED CHECK POINTS (final; shown after all checks):"
_RECORDED_FAILURE_NOTE = "see final failed check points"
_RECORDED_TEST_FAILURE_NOTE = "see final failed check points"
_INLINE_FAILURE_OUTPUT_FORBIDDEN_MARKERS = ("Traceback",)
_FAILURE_POINT_PRIORITY_KEYS = (
    "error",
    "errors",
    "exception",
    "traceback",
    "found",
    "relative",
    "docPrefix",
    "docLineCount",
    "pyCount",
    "actual",
    "expected",
    "result",
    "ok",
)


def _record_failure(label: str, detail: str = "") -> None:
    failure_label = str(label or "").strip() or "(unlabeled check)"
    if (
        _CURRENT_TEST_LABEL
        and failure_label != _CURRENT_TEST_LABEL
        and not failure_label.startswith(f"{_CURRENT_TEST_LABEL} / ")
    ):
        failure_label = f"{_CURRENT_TEST_LABEL} / {failure_label}"
    _FAILURES.append((failure_label, str(detail or "")))


def _flush_test_output() -> None:
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.flush()
        except Exception:
            pass


def _route_selftest_diagnostics_to_stdout() -> None:
    """Keep expected diagnostic logs in chronological selftest output."""
    sys.stderr = sys.stdout
    loggers = [logging.getLogger()]
    loggers.extend(
        logger for logger in logging.root.manager.loggerDict.values()
        if isinstance(logger, logging.Logger)
    )
    handlers = []
    for logger in loggers:
        handlers.extend(logger.handlers)
    if logging.lastResort is not None:
        handlers.append(logging.lastResort)
    for handler in handlers:
        try:
            handler.setStream(sys.stdout)
        except Exception:
            if hasattr(handler, "stream"):
                try:
                    handler.stream = sys.stdout
                except Exception:
                    pass


def _check(label: str, ok: bool, detail: str = "") -> None:
    global _PASS, _FAIL
    if ok:
        _PASS += 1
        print(f"  ✓ {label}")
    else:
        _FAIL += 1
        _record_failure(label, detail)
        print(f"  ✗ failure #{len(_FAILURES)} recorded; {_RECORDED_FAILURE_NOTE}")


def _subprocess_failure_detail(result, success_marker: str = "") -> str:
    stdout = str(getattr(result, "stdout", "") or "").strip()
    stderr = str(getattr(result, "stderr", "") or "").strip()
    lines = [f"returncode={getattr(result, 'returncode', '(missing)')}"]
    if success_marker and success_marker not in stdout:
        lines.append(f"missing stdout marker: {success_marker}")
    for stream_name, stream_text in (("stdout", stdout), ("stderr", stderr)):
        if not stream_text:
            continue
        lines.append(f"{stream_name}:")
        lines.extend(f"  {line}" for line in _failure_detail_tail(stream_text))
    return "\n".join(lines)


def _check_subprocess_result(label: str, result, success_marker: str = "") -> None:
    stdout = str(getattr(result, "stdout", "") or "")
    ok = getattr(result, "returncode", None) == 0
    if success_marker:
        ok = ok and success_marker in stdout
    _check(label, ok, _subprocess_failure_detail(result, success_marker))


def _run_test(label: str, fn) -> None:
    global _FAIL, _CURRENT_TEST_LABEL
    previous_test_label = _CURRENT_TEST_LABEL
    _CURRENT_TEST_LABEL = label
    try:
        try:
            fn()
        except BaseException as exc:
            if isinstance(exc, KeyboardInterrupt):
                raise
            _FAIL += 1
            detail = f"{type(exc).__name__}: {exc}\n{traceback.format_exc().rstrip()}"
            _record_failure(label, detail)
            print(f"  ✗ failure #{len(_FAILURES)} recorded; {_RECORDED_TEST_FAILURE_NOTE}")
    finally:
        _CURRENT_TEST_LABEL = previous_test_label


def _failure_detail_tail(detail: str) -> list[str]:
    lines = str(detail or "").splitlines()
    if len(lines) <= _FAILURE_DETAIL_LINE_LIMIT:
        return lines
    omitted = len(lines) - _FAILURE_DETAIL_LINE_LIMIT
    return [f"... omitted {omitted} earlier detail lines ...", *lines[-_FAILURE_DETAIL_LINE_LIMIT:]]


def _failure_point_value_is_suspicious(key: str, value) -> bool:
    key_lower = str(key or "").lower()
    if value is None:
        return True
    if isinstance(value, str):
        return value == ""
    if isinstance(value, (list, tuple, dict, set)):
        return len(value) == 0
    if isinstance(value, bool):
        return value is False and (
            key_lower in {"ok", "success", "matched", "found", "exists"}
        )
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return value == 0 and key_lower.endswith(("count", "linecount", "size", "length"))
    return False


def _failure_point_format_value(value) -> str:
    try:
        text = json.dumps(value, ensure_ascii=False, sort_keys=True)
    except Exception:
        text = repr(value)
    if len(text) > 48:
        text = f"{text[:45]}..."
    return text


def _failure_point_collect_json_hints(value, path: str = "") -> list[str]:
    hints: list[tuple[int, str]] = []

    def _priority(key: str) -> int:
        if key in _FAILURE_POINT_PRIORITY_KEYS:
            return _FAILURE_POINT_PRIORITY_KEYS.index(key)
        key_lower = key.lower()
        for index, priority_key in enumerate(_FAILURE_POINT_PRIORITY_KEYS):
            if key_lower == priority_key.lower():
                return index
        return len(_FAILURE_POINT_PRIORITY_KEYS)

    def _visit(node, node_path: str) -> None:
        if len(hints) >= _FAILURE_POINT_HINT_LIMIT * 3:
            return
        if isinstance(node, dict):
            for key, item in node.items():
                key_text = str(key)
                item_path = f"{node_path}.{key_text}" if node_path else key_text
                if _failure_point_value_is_suspicious(key_text, item):
                    hints.append((
                        _priority(key_text),
                        f"{item_path}={_failure_point_format_value(item)}",
                    ))
                elif isinstance(item, (dict, list, tuple)):
                    _visit(item, item_path)
            return
        if isinstance(node, (list, tuple)):
            for index, item in enumerate(node[:4]):
                if isinstance(item, (dict, list, tuple)):
                    _visit(item, f"{node_path}[{index}]")

    _visit(value, path)
    hints.sort(key=lambda item: item[0])
    return [hint for _, hint in hints[:_FAILURE_POINT_HINT_LIMIT]]


def _failure_point_json_reason(text: str) -> str:
    stripped = str(text or "").strip()
    if not stripped or stripped[0] not in "[{":
        return ""
    try:
        data = json.loads(stripped)
    except Exception:
        return ""
    hints = _failure_point_collect_json_hints(data)
    if not hints:
        return ""
    reason = "suspect fields: " + ", ".join(hints)
    if len(reason) > _FAILURE_POINT_LINE_LIMIT:
        return f"{reason[:_FAILURE_POINT_LINE_LIMIT - 3]}..."
    return reason


def _failure_point_reason(detail: str) -> str:
    for line in str(detail or "").splitlines():
        text = line.strip()
        if text:
            json_reason = _failure_point_json_reason(text)
            if json_reason:
                return json_reason
            if len(text) > _FAILURE_POINT_LINE_LIMIT:
                return f"{text[:_FAILURE_POINT_LINE_LIMIT - 3]}..."
            return text
    return "no detail recorded"


def _failed_check_point_lines(
    failures: list[tuple[str, str]] | None = None,
) -> list[str]:
    failure_items = _FAILURES if failures is None else failures
    if not failure_items:
        return ["  1. Unknown failure; no failure detail was recorded."]
    return [
        f"  {index}. {label}: {_failure_point_reason(detail)}"
        for index, (label, detail) in enumerate(failure_items, 1)
    ]


def _final_failed_check_point_lines(
    failures: list[tuple[str, str]] | None = None,
) -> list[str]:
    failure_items = _FAILURES if failures is None else failures
    if not failure_items:
        return _failed_check_point_lines(failure_items)

    lines: list[str] = []
    for index, (label, detail) in enumerate(failure_items, 1):
        lines.append(f"  {index}. {label}: {_failure_point_reason(detail)}")
        detail_lines = _failure_detail_tail(detail)
        if not detail_lines:
            continue
        lines.append("     detail:")
        lines.extend(f"       {line}" for line in detail_lines)
    return lines


def _inline_failure_output_is_deferred(output: str, hidden_markers: list[str]) -> bool:
    text = str(output or "")
    return all(marker not in text for marker in [
        *hidden_markers,
        *_INLINE_FAILURE_OUTPUT_FORBIDDEN_MARKERS,
    ])


def _print_final_failed_check_points() -> None:
    print(f"{'=' * 50}")
    print(_FINAL_FAILURE_POINT_HEADING)
    for line in _final_failed_check_point_lines():
        print(line)


def _print_final_summary(total: int) -> None:
    print(f"{'=' * 50}")
    if _FAIL == 0:
        print(f"ALL {total} TESTS PASSED ✓")
        print(f"{'=' * 50}")
        return

    print(f"{_PASS}/{total} passed, {_FAIL} FAILED ✗")
    print(f"{'=' * 50}")
    print()
    _print_final_failed_check_points()


def _wait_until(predicate, timeout: float = 2.0) -> bool:
    deadline = time.time() + timeout
    while time.time() < deadline:
        if predicate():
            return True
        time.sleep(0.05)
    return predicate()


def _extract_js_function(html: str, name: str) -> str:
    marker = f"function {name}("
    start = html.find(marker)
    if start < 0:
        raise ValueError(f"Missing JS function: {name}")
    if start >= 6 and html[start - 6:start] == "async ":
        start -= 6
    brace = html.find("{", start)
    if brace < 0:
        raise ValueError(f"Missing JS function body: {name}")
    depth = 0
    in_quote = ""
    escaped = False
    in_line_comment = False
    in_block_comment = False
    for index in range(brace, len(html)):
        ch = html[index]
        nxt = html[index + 1] if index + 1 < len(html) else ""
        if in_line_comment:
            if ch == "\n":
                in_line_comment = False
            continue
        if in_block_comment:
            if ch == "*" and nxt == "/":
                in_block_comment = False
            continue
        if escaped:
            escaped = False
            continue
        if in_quote:
            if ch == "\\":
                escaped = True
            elif ch == in_quote:
                in_quote = ""
            continue
        if ch in ("'", '"', "`"):
            in_quote = ch
            continue
        if ch == "/" and nxt == "/":
            in_line_comment = True
            continue
        if ch == "/" and nxt == "*":
            in_block_comment = True
            continue
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return html[start:index + 1]
    raise ValueError(f"Unterminated JS function: {name}")


def test_selftest_output() -> None:
    print("-- Selftest Output --")
    sample_failures = [
        ("Imports / llm_engine", "ImportError: missing module\ntrace tail"),
        ("Bridge / command dispatch", ""),
    ]
    point_lines = _failed_check_point_lines(sample_failures)
    _check("failed check point lines include first detail",
           point_lines == [
               "  1. Imports / llm_engine: ImportError: missing module",
               "  2. Bridge / command dispatch: no detail recorded",
           ])
    json_reason = _failure_point_reason(json.dumps({
        "ok": True,
        "workspaceFolderDuplicateOk": False,
        "found": [],
        "relative": "",
        "docPrefix": "",
        "docLineCount": 0,
        "pyCount": 0,
    }))
    _check("json failure point highlights suspect fields",
           "found=[]" in json_reason
           and 'relative=""' in json_reason
           and 'docPrefix=""' in json_reason
           and "pyCount=0" in json_reason)
    _check("json failure point keeps expected false flags out",
           "workspaceFolderDuplicateOk" not in json_reason)

    global _PASS, _FAIL
    saved_pass = _PASS
    saved_fail = _FAIL
    saved_failures = list(_FAILURES)
    saved_stdout = sys.stdout

    inline_capture = io.StringIO()
    try:
        sys.stdout = inline_capture
        _check("inline failure label", False, "secret inline detail")
    finally:
        sys.stdout = saved_stdout
        _PASS = saved_pass
        _FAIL = saved_fail
        _FAILURES[:] = saved_failures

    inline_output = inline_capture.getvalue()
    _check("check failure output defers failure point",
           _RECORDED_FAILURE_NOTE in inline_output
           and "failure #1 recorded" in inline_output
           and _inline_failure_output_is_deferred(
               inline_output,
               ["inline failure label", "secret inline detail"],
           ))

    class _FakeSubprocessResult:
        returncode = 7
        stdout = "visible setup\nsecret stdout detail"
        stderr = "secret stderr detail"

    subprocess_capture = io.StringIO()
    try:
        sys.stdout = subprocess_capture
        _check_subprocess_result(
            "Subprocess Output Test",
            _FakeSubprocessResult(),
            "expected marker",
        )
    finally:
        sys.stdout = saved_stdout
        _PASS = saved_pass
        _FAIL = saved_fail
        _FAILURES[:] = saved_failures

    subprocess_output = subprocess_capture.getvalue()
    _check("subprocess failure output defers captured streams",
           _RECORDED_FAILURE_NOTE in subprocess_output
           and "failure #1 recorded" in subprocess_output
           and _inline_failure_output_is_deferred(
               subprocess_output,
               [
                   "Subprocess Output Test",
                   "secret stdout detail",
                   "secret stderr detail",
                   "expected marker",
               ],
           ))
    subprocess_detail = _subprocess_failure_detail(
        _FakeSubprocessResult(),
        "expected marker",
    )
    _check("subprocess failure detail keeps final diagnostics",
           "returncode=7" in subprocess_detail
           and "missing stdout marker: expected marker" in subprocess_detail
           and "secret stdout detail" in subprocess_detail
           and "secret stderr detail" in subprocess_detail)

    exception_capture = io.StringIO()
    try:
        sys.stdout = exception_capture

        def _selftest_output_raises() -> None:
            raise RuntimeError("secret exception detail")

        _run_test("Exploding Output Test", _selftest_output_raises)
    finally:
        sys.stdout = saved_stdout
        _PASS = saved_pass
        _FAIL = saved_fail
        _FAILURES[:] = saved_failures

    exception_output = exception_capture.getvalue()
    _check("test exception output defers traceback",
           _RECORDED_TEST_FAILURE_NOTE in exception_output
           and "failure #1 recorded" in exception_output
           and _inline_failure_output_is_deferred(
               exception_output,
               ["Exploding Output Test", "secret exception detail"],
           ))

    system_exit_capture = io.StringIO()
    try:
        sys.stdout = system_exit_capture

        def _selftest_output_exits() -> None:
            raise SystemExit("secret system exit detail")

        _run_test("SystemExit Output Test", _selftest_output_exits)
    finally:
        sys.stdout = saved_stdout
        _PASS = saved_pass
        _FAIL = saved_fail
        _FAILURES[:] = saved_failures

    system_exit_output = system_exit_capture.getvalue()
    _check("test SystemExit output defers failure point",
           _RECORDED_TEST_FAILURE_NOTE in system_exit_output
           and "failure #1 recorded" in system_exit_output
           and _inline_failure_output_is_deferred(
               system_exit_output,
               ["SystemExit Output Test", "secret system exit detail"],
           ))

    capture = io.StringIO()
    try:
        _PASS = 3
        _FAIL = 2
        _FAILURES[:] = sample_failures
        sys.stdout = capture
        _print_final_summary(5)
    finally:
        sys.stdout = saved_stdout
        _PASS = saved_pass
        _FAIL = saved_fail
        _FAILURES[:] = saved_failures

    output_lines = capture.getvalue().splitlines()
    points_index = output_lines.index(_FINAL_FAILURE_POINT_HEADING)
    _check("failure details are not printed before final failure points",
           "FAILED CHECK DETAILS:" not in output_lines)
    _check("failure point list is the final output block",
           output_lines[points_index - 1] == ("=" * 50)
           and output_lines[points_index + 1:] == [
               "  1. Imports / llm_engine: ImportError: missing module",
               "     detail:",
               "       ImportError: missing module",
               "       trace tail",
               "  2. Bridge / command dispatch: no detail recorded",
           ])
    _check("final failure point block includes detail tail",
           "       trace tail" in output_lines[points_index + 1:])


