class _FakeGui:
    settings = None
    _ai_engine_actions = {"sample_state": lambda **kw: {"ok": True, "source": "plugin"}}
    _plugin_manager = None
    _packet_bridge = None
    _mem_bridge = None
    _start_time = 0.0


class _FakeSettings:
    def __init__(self, data):
        self.data = data
        self.saved = False

    def get(self, key, default=None):
        return self.data.get(key, default)

    def set(self, key, value):
        self.data[key] = value

    def save(self):
        self.saved = True


class _FailingSettings(_FakeSettings):
    def save(self):
        raise RuntimeError("disk failed")


class _SettingsGui(_FakeGui):
    def __init__(self, data):
        self.settings = _FakeSettings(data)
        self._ai_engine_actions = dict(_FakeGui._ai_engine_actions)


class _FailingSettingsGui(_FakeGui):
    def __init__(self, data):
        self.settings = _FailingSettings(data)
        self._ai_engine_actions = dict(_FakeGui._ai_engine_actions)


class _FakeVscodeNamespace:
    def __init__(self, html_by_id=None):
        self.html_by_id = dict(html_by_id or {})
        self.delivered = []

    def get_webview_html(self, view_id):
        return self.html_by_id.get(view_id, "")

    def list_webview_view_ids(self):
        return list(self.html_by_id.keys())

    def list_webview_views(self):
        return [
            {
                "view_id": view_id,
                "kind": "webviewView",
                "extension_id": "",
                "title": view_id,
                "html_available": bool(html),
            }
            for view_id, html in self.html_by_id.items()
        ]

    def deliver_webview_message(self, view_id, message):
        if view_id not in self.html_by_id:
            return False
        self.delivered.append((view_id, message))
        return True


class _FakeExtPoints:
    def __init__(self, all_contributions):
        self.all_contributions = all_contributions


class _FakeExtDesc:
    """Minimal extension descriptor for selftest manifest-view lookup."""
    def __init__(self, ext_id, contributes=None, enabled=True, publisher=""):
        self.id = ext_id
        self.contributes = contributes or {}
        self.enabled = enabled
        self.publisher = publisher or ext_id.split(".", 1)[0] if "." in ext_id else ""


class _FakeRegistry:
    def __init__(self, extensions=None):
        self._extensions = list(extensions or [])

    def list_all(self):
        return list(self._extensions)


class _FakeExtensionHost:
    def __init__(self, all_contributions):
        self.ext_points = _FakeExtPoints(all_contributions)
        self.registry = _FakeRegistry(
            self._build_fake_extensions(all_contributions)
        )
        self.activated_events = []

    def activate_event(self, event):
        self.activated_events.append(event)
        return []

    @staticmethod
    def _build_fake_extensions(contribs):
        """Synthesize _FakeExtDesc entries from all_contributions['views']."""
        views_by_location = contribs.get("views", {})
        if not views_by_location:
            return []
        by_ext: dict = {}
        for location, views in views_by_location.items():
            if not isinstance(views, list):
                continue
            for view in views:
                ext_id = view.get("_extensionId", "unknown.ext")
                if ext_id not in by_ext:
                    by_ext[ext_id] = {}
                by_ext[ext_id].setdefault(location, []).append(view)
        result = []
        for ext_id, loc_views in by_ext.items():
            result.append(_FakeExtDesc(
                ext_id=ext_id,
                contributes={"views": loc_views},
            ))
        return result


class _FakeNodeCustomEditorHost:
    is_running = True

    def __init__(self):
        self.requests = []
        self.relayed = []
        self.notebook_deserialize_requests = []
        self.notebook_serialize_requests = []
        self.notebook_controller_requests = []

    def request_custom_editor_result(
            self, view_type, uri, title="", view_id="", timeout=2.0):
        self.requests.append({
            "view_type": view_type,
            "uri": uri,
            "title": title,
            "view_id": view_id,
            "timeout": timeout,
        })
        return {
            "ok": True,
            "viewId": "custom-selftest-1",
            "uri": f"file:///{os.path.basename(str(uri))}",
        }

    def custom_editor_state(self, view_id="", view_type="", uri=""):
        return {
            "viewId": view_id or "custom-selftest-1",
            "viewType": view_type or "selftest.customNbt",
            "uri": uri or "file:///fake.nbt",
            "dirty": False,
        }

    def list_custom_editor_states(self):
        return [self.custom_editor_state()]

    def request_custom_editor_lifecycle(
            self, action, view_type="", uri="", view_id="", target="",
            timeout=2.0):
        return {
            "ok": True,
            "action": action,
            "viewId": view_id or "custom-selftest-1",
            "viewType": view_type or "selftest.customNbt",
            "uri": uri or "file:///fake.nbt",
            "dirty": False,
            "canUndo": False,
            "canRedo": action == "undo",
            "state": {
                "viewId": view_id or "custom-selftest-1",
                "viewType": view_type or "selftest.customNbt",
                "uri": uri or "file:///fake.nbt",
                "dirty": False,
                "canUndo": False,
                "canRedo": action == "undo",
            },
        }

    def relay_webview_message(self, view_id, message):
        self.relayed.append((view_id, message))
        return True

    def dispose_webview_panel(self, view_id):
        self.relayed.append(("dispose", view_id))
        return True

    def notebook_serializers(self):
        return [{
            "handle": 7,
            "viewType": "selftest.notebook",
            "extensionId": "selftest.notebookExt",
            "options": {},
        }]

    def is_extension_activated(self, ext_id):
        return True

    def request_notebook_deserialize_result(
            self, data, handle=None, view_type="", default=None,
            timeout=3.0):
        self.notebook_deserialize_requests.append({
            "data": data,
            "handle": handle,
            "view_type": view_type,
            "timeout": timeout,
        })
        return {
            "ok": True,
            "value": {
                "metadata": {"fixture": True},
                "cells": [{
                    "kind": 2,
                    "value": "print('nb')",
                    "languageId": "python",
                    "outputs": [{
                        "id": "out-1",
                        "items": [{
                            "mime": "text/plain",
                            "dataText": "ok",
                        }],
                    }],
                }],
            },
            "handle": handle,
            "viewType": view_type,
        }

    def request_notebook_serialize_result(
            self, notebook, handle=None, view_type="", default=None,
            timeout=3.0):
        self.notebook_serialize_requests.append({
            "notebook": notebook,
            "handle": handle,
            "view_type": view_type,
            "timeout": timeout,
        })
        return {
            "ok": True,
            "response": {
                "dataText": json.dumps(notebook, ensure_ascii=False),
            },
            "handle": handle,
            "viewType": view_type,
        }

    def notebook_controllers(self):
        return [{
            "handle": 11,
            "id": "selftest.notebookController",
            "notebookType": "selftest.notebook",
            "label": "Selftest Kernel",
            "description": "Python",
            "detail": "Selftest detail",
            "supportedLanguages": ["python"],
            "supportsExecutionOrder": True,
            "extensionId": "selftest.notebookExt",
        }]

    def request_notebook_controllers_result(
            self, notebook_type="", default=None, timeout=3.0):
        controllers = [
            item for item in self.notebook_controllers()
            if not notebook_type or item.get("notebookType") == notebook_type
        ]
        return {"ok": True, "value": controllers}

    def notebook_controller_detection_tasks(self, notebook_type=""):
        task = {
            "notebookType": "selftest.notebook",
            "extensionId": "selftest.notebookExt",
        }
        if notebook_type and notebook_type != task["notebookType"]:
            return []
        return [task]

    def select_notebook_controller_result(
            self, uri, notebook, view_type="", handle=None, controller_id="",
            selected=True, default=None, timeout=3.0):
        self.notebook_controller_requests.append({
            "action": "select",
            "uri": uri,
            "view_type": view_type,
            "handle": handle,
            "controller_id": controller_id,
            "selected": selected,
        })
        controller = self.notebook_controllers()[0]
        return {
            "ok": True,
            "value": {
                "controller": controller,
                "selected": bool(selected),
                "uri": uri,
            },
        }

    def execute_notebook_controller_result(
            self, uri, notebook, view_type="", handle=None, controller_id="",
            cell_indices=None, default=None, timeout=5.0):
        self.notebook_controller_requests.append({
            "action": "execute",
            "uri": uri,
            "view_type": view_type,
            "handle": handle,
            "controller_id": controller_id,
            "cell_indices": cell_indices,
        })
        next_notebook = json.loads(json.dumps(notebook))
        for order, index in enumerate(cell_indices or [], start=1):
            try:
                cell = next_notebook.setdefault("cells", [])[int(index)]
            except (IndexError, TypeError, ValueError):
                continue
            cell["internalMetadata"] = {
                **(cell.get("internalMetadata") or {}),
                "executionOrder": order,
            }
            cell["outputs"] = [{
                "id": f"exec-{index}",
                "items": [{
                    "mime": "text/plain",
                    "dataText": f"executed:{index}",
                }],
            }]
        return {
            "ok": True,
            "value": {
                "controller": self.notebook_controllers()[0],
                "cellCount": len(cell_indices or []),
                "cellIndices": list(cell_indices or []),
                "notebook": next_notebook,
            },
        }


def test_app_settings_parity() -> None:
    print("── App Settings Parity ──")
    from ai_editor.app import AIEditorAPI, _activate_window_handle, _normalize_window_geometry

