        class _TaskProvider:
            def provideTasks(self):
                return [{
                    "type": "selftest",
                    "label": "echo task",
                    "command": sys.executable,
                    "args": ["-c", "print('task ok')"],
                }]

        task_start = []
        task_end = []
        api["tasks"]["onDidStartTask"](lambda evt: task_start.append(evt))
        api["tasks"]["onDidEndTask"](lambda evt: task_end.append(evt))
        api["tasks"]["registerTaskProvider"]("selftest", _TaskProvider())
        fetched_tasks = api["tasks"]["fetchTasks"]({"type": "selftest"})
        task_execution = api["tasks"]["executeTask"](fetched_tasks[0])
        task_done = _wait_until(lambda: task_execution.exitStatus is not None)
        _check("tasks.executeTask runs local commands and updates lifecycle",
               len(fetched_tasks) == 1
               and task_execution.processId is not None
               and task_done
               and task_execution.exitStatus.get("code") == 0
               and len(task_start) == 1
               and len(task_end) == 1
               and api["tasks"]["taskExecutions"] == [])
        long_task_done = threading.Event()

        class _LongTaskProvider:
            def provideTasks(self):
                return [{
                    "type": "selftest-long",
                    "label": "long task",
                    "run": lambda: long_task_done.wait(1.0),
                }]

        api["tasks"]["registerTaskProvider"](
            "selftest-long", _LongTaskProvider())
        long_task = api["tasks"]["fetchTasks"]({"type": "selftest-long"})[0]
        long_execution = api["tasks"]["executeTask"](long_task)
        task_running = _wait_until(
            lambda: ns.runtime_context_snapshot().get("taskRunning") is True)
        long_task_done.set()
        long_task_finished = _wait_until(
            lambda: long_execution.exitStatus is not None)
        _check("task runtime context tracks active task execution",
               task_running
               and long_task_finished
               and ns.runtime_context_snapshot().get("taskRunning") is False)

